// Two variable definitions
const vol = [20.0, 25.0, 30.0, 35.0, 40.0, 45.0, 50.0, 55.0, 60.0, 65.0, 70.0, 75.0, 80.0, 85.0, 90.0];
const v = OLI.random(0,14,0);
const volweakacid = vol[v];
const volweakacidsf = volweakacid .toFixed(2); //display value
const ka = 6.4e-5;

const conc = [0.20, 0.25, 0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65, 0.7, 0.75, 0.8, 0.85, 0.9];
const c1 = OLI.random(0,14,0);
const c2 = OLI.random(0,14,0);
const concacid = conc[c1];
const conckoh = conc[c2];
const concacidsf = conc[c1] .toPrecision(3); //display value
const conckohsf = conc[c2] .toPrecision(3); //display value

//Initial pH
// Solve by iteration
var x = 0;
for (let step = 0; step < 10; step++) {
  x = Math.sqrt(ka*(concacid-x));
}

const h3o1 = x .toPrecision(3);
const ph1 = -Math.log10(x);
const ph1sf = ph1 .toPrecision(3);
const ph1low = 0.99*ph1;
const ph1high = 1.01*ph1;

//pH before equivalence point (buffer region)
const eqpt = concacid*volweakacid/conckoh;
const eqptsf = eqpt .toFixed(2);
const mmola = concacid*volweakacid;
const mola = mmola/1000;
const molasf = mola .toPrecision(4);
const moleqpt = conckoh*eqpt/1000;
const moleqptsf = moleqpt .toPrecision(4)

const mmoloh = OLI.random(0.2*mmola,0.8*mmola,1);
const volbefore =(mmoloh/conckoh);
const volbeforesf = volbefore .toPrecision(3);

const molb = conckoh*volbefore/1000;
const molbsf = molb .toPrecision(3);
const molaafter = molasf-molbsf;
const molaaftersf = molaafter .toPrecision(3);
const ratio = molb/molaafter;
const ratiosf = ratio .toPrecision(3);
const pka = -Math.log10(ka);
const ph2 = pka + Math.log10(molb/molaafter);
const ph2sf = ph2 .toPrecision(3);
const ph2low = 0.99*ph2;
const ph2high = 1.01*ph2;

//pH @ Equivalence point
const veq = volweakacid + eqpt;
const veqsf = veq .toPrecision(3);
const veqL = veq/1000;
const veqLsf = veqL .toPrecision(3);
const concweakbase = mola/(veq/1000);
const concweakbasesf = concweakbase .toPrecision(3);
const kb = 1.6e-10;
const kbsf = kb .toPrecision(3);

var y = 0;
for (let step = 0; step < 10; step++) {
  y = Math.sqrt(kb*(concweakbase-y));
}
const ysf = y .toPrecision(3);
const poh3 = -Math.log10(y);
const poh3sf = poh3 .toPrecision(3);
const ph3 = 14-poh3;
const ph3sf = ph3 .toPrecision(3);
const ph3low = 0.99*ph3;
const ph3high = 1.01*ph3;

//pH after Equivalence point
const vafter = OLI.random(1.15*eqpt,1.45*eqpt,1);
const vaftersf = vafter .toPrecision(3);
const molohafter = vafter*conckoh/1000;
const molohaftersf = molohafter .toPrecision(3);
const molohxs = molohaftersf - molasf;
const molohxssf = molohxs .toPrecision(3);
const totvolafter = vafter + volweakacid;
const totvolaftersf = totvolafter .toPrecision(3);
const totvolafterL = totvolaftersf/1000;
const totvolafterLsf = totvolafterL .toPrecision(3);
const excessbase = vafter*conckoh/1000 - mola;
const concexcessbase = excessbase/((volweakacid+vafter)/1000);
const concohxs = molohxssf/totvolafterLsf;
const concohxssf = concohxs .toPrecision(3);
const poh4 = -Math.log10(concohxssf);
const poh4sf = poh4 .toPrecision(3);
const ph4 = 14-poh4;
const ph4sf = ph4 .toPrecision(4);
const ph4low = 0.99*ph4;
const ph4high = 1.01*ph4;

// Expose variables to OLI
module.exports = {
  volweakacid, volweakacidsf, concacid, concacidsf, conckoh, conckohsf, h3o1, ph1sf, ph1low, ph1high, eqpt, eqptsf, molasf, moleqptsf, volbeforesf, molbsf, 
  molaafter, molaaftersf, ratiosf, ph2, ph2sf, ph2low, ph2high, veqsf, veqLsf, concweakbase, concweakbasesf, y, ysf, poh3sf, ph3sf, ph3low, ph3high, vafter, vaftersf, molohafter, molohaftersf,  
  molohxssf, totvolaftersf, totvolafterLsf, excessbase, concexcessbase, concohxssf, poh4, poh4sf, ph4, ph4sf, ph4low, ph4high
};
